mapper.select:
SELECT rno, rtitle, rimage, rjobrole, rsummary, rcreate, rupdate, mno
FROM resume
WHERE rno = #{rno} AND mno = #{mno}

mapper.update:
UPDATE resume
SET rtitle = #{rtitle},
    rjobrole = #{rjobrole, jdbcType=VARCHAR},
    rsummary = #{rsummary, jdbcType=VARCHAR},
    rupdate = SYSDATE

      , rimage = #{rimage, jdbcType=VARCHAR}

WHERE rno = #{rno}
  AND mno = #{mno}

mapper.delete:
DELETE FROM resume
WHERE rno = #{rno}
  AND mno = #{mno}

