mapper.insert:
INSERT INTO resume_education (reno, reschoolname, remajor, redegree, restartdate, reenddate, rno) SELECT RESUME_EDUCATION_SEQ.NEXTVAL, a.* FROM (
SELECT #{e.reschoolname, jdbcType=VARCHAR}, #{e.remajor, jdbcType=VARCHAR}, #{e.redegree, jdbcType=VARCHAR}, CASE WHEN #{e.restartdate, jdbcType=VARCHAR} IS NULL OR #{e.restartdate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{e.restartdate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, CASE WHEN #{e.reenddate, jdbcType=VARCHAR} IS NULL OR #{e.reenddate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{e.reenddate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, #{rno} FROM dual
) a

INSERT INTO resume_career (rcno, rccompany, rcposition, rcstartdate, rcenddate, rccurrent, rcdescription, rno) SELECT RESUME_CAREER_SEQ.NEXTVAL, a.* FROM (
SELECT #{c.rccompany, jdbcType=VARCHAR}, #{c.rcposition, jdbcType=VARCHAR}, CASE WHEN #{c.rcstartdate, jdbcType=VARCHAR} IS NULL OR #{c.rcstartdate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{c.rcstartdate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, CASE WHEN #{c.rcenddate, jdbcType=VARCHAR} IS NULL OR #{c.rcenddate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{c.rcenddate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, #{c.rccurrent, jdbcType=VARCHAR}, #{c.rcdescription, jdbcType=VARCHAR}, #{rno} FROM dual
) a

INSERT INTO resume_project (rpno, rpname, rpstartdate, rpenddate, rpsummary, rpcontent, rplink, rno) SELECT RESUME_PROJECT_SEQ.NEXTVAL, a.* FROM (
SELECT #{item.rpname, jdbcType=VARCHAR}, CASE WHEN #{item.rpstartdate, jdbcType=VARCHAR} IS NULL OR #{item.rpstartdate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{item.rpstartdate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, CASE WHEN #{item.rpenddate, jdbcType=VARCHAR} IS NULL OR #{item.rpenddate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{item.rpenddate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, #{item.rpsummary, jdbcType=VARCHAR}, #{item.rpcontent, jdbcType=VARCHAR}, #{item.rplink, jdbcType=VARCHAR}, #{rno} FROM DUAL
) a

INSERT INTO resume_other (rono, rotype, rotitle, roorg, rodate, rno) SELECT RESUME_OTHER_SEQ.NEXTVAL, a.* FROM (
SELECT #{item.rotype, jdbcType=VARCHAR}, #{item.rotitle, jdbcType=VARCHAR}, #{item.roorg, jdbcType=VARCHAR}, #{item.rodate, jdbcType=DATE}, #{rno} FROM DUAL
) a

INSERT INTO resume_training (rtno, rtorg, rtstartdate, rtenddate, rtcontent, rno) SELECT RESUME_TRAINING_SEQ.NEXTVAL, a.* FROM (
SELECT #{item.rtorg, jdbcType=VARCHAR}, CASE WHEN #{item.rtstartdate, jdbcType=VARCHAR} IS NULL OR #{item.rtstartdate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{item.rtstartdate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, CASE WHEN #{item.rtenddate, jdbcType=VARCHAR} IS NULL OR #{item.rtenddate, jdbcType=VARCHAR} = '' THEN NULL ELSE TO_DATE(#{item.rtenddate, jdbcType=VARCHAR} || '-01', 'YYYY-MM-DD') END, #{item.rtcontent, jdbcType=VARCHAR}, #{rno} FROM DUAL
) a
